from solution import hamming_Distance
import inspect


def test_issue_example_4_8():
    """Example: hamming_Distance(4,8) == 2."""
    assert hamming_Distance(4, 8) == 2  # 4=0b100, 8=0b1000, xor=0b1100 has 2 ones


def test_issue_identical_values():
    """Find hamming distance between given two integers."""
    assert hamming_Distance(7, 7) == 0  # 7 xor 7 = 0 = 0b0 has 0 ones


def test_issue_both_zero():
    """Find hamming distance between given two integers."""
    assert hamming_Distance(0, 0) == 0  # 0 xor 0 = 0 = 0b0 has 0 ones


def test_issue_zero_vs_one():
    """Find hamming distance between given two integers."""
    assert hamming_Distance(0, 1) == 1  # 0=0b0, 1=0b1, xor=0b1 has 1 one


def test_issue_zero_vs_power_of_two():
    """Find hamming distance between given two integers."""
    assert hamming_Distance(0, 8) == 1  # 0=0b0000, 8=0b1000, xor=0b1000 has 1 one


def test_issue_single_bit_flip():
    """Find hamming distance between given two integers."""
    assert hamming_Distance(4, 5) == 1  # 4=0b100, 5=0b101, xor=0b001 has 1 one


def test_issue_different_bit_lengths():
    """Find hamming distance between given two integers."""
    assert hamming_Distance(1, 2) == 2  # 1=0b01, 2=0b10, xor=0b11 has 2 ones


def test_issue_complementary_nibbles():
    """Find hamming distance between given two integers."""
    assert hamming_Distance(10, 5) == 4  # 10=0b1010, 5=0b0101, xor=0b1111 has 4 ones


def test_issue_zero_vs_all_ones_byte():
    """Find hamming distance between given two integers."""
    assert hamming_Distance(0, 255) == 8  # 255=0b11111111 has 8 ones, xor=0b11111111


def test_issue_large_boundary_values():
    """Find hamming distance between given two integers."""
    assert hamming_Distance(1023, 1024) == 11  # 1023=10 ones, 1024=0b10000000000, xor=0b11111111111 has 11 ones


def test_contract_returns_int():
    """Function finds hamming distance as integer."""
    assert isinstance(hamming_Distance(4, 8), int)  # example distance 2 is of type int


def test_contract_takes_n1_n2():
    """Public interface is hamming_Distance(n1, n2)."""
    assert list(inspect.signature(hamming_Distance).parameters) == ["n1", "n2"]  # params are n1 and n2
